package com.zeroToHero.corejava.loops;

public class MainFor {

	public static void main(String[] args) {
		
		// TODO Auto-generated method stub    
		
		int num = 0;
		
		for(int j = 1; j<=10;j++) {
			num = num+j;
		}
		
		System.out.println("The num of first 10 natural numbers is : "+num);
		
	}
}
